import React, { useState, useEffect } from "react";
import axios from "axios";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";

export default function Match({ userEmail }) {
  const [entryFee, setEntryFee] = useState(13);
  const [status, setStatus] = useState("");
  const [game, setGame] = useState(null);
  const [playerId, setPlayerId] = useState(null);
  const [loading, setLoading] = useState(false);

  const ALLOWED_FEES = [13, 23, 50];

  useEffect(() => {
    if (!game?.id) return;

    const token = localStorage.getItem("authToken");
    const socket = new SockJS(`http://localhost:8080/ludo-ws?token=${token}`); // ✅ token added

    const client = new Client({
      webSocketFactory: () => socket,
      onConnect: () => {
        client.subscribe(`/topic/match/${game.id}`, (message) => {
          const gameSession = JSON.parse(message.body);
          setGame(gameSession);
          setStatus("🎮 Game started! Good luck!");
        });
      },
      onStompError: (frame) => {
        console.error("STOMP error:", frame);
        setStatus("❌ WebSocket connection error.");
      },
    });

    client.activate();

    return () => {
      client.deactivate();
    };
  }, [game?.id]);

  const handleMatchRequest = async () => {
    if (!ALLOWED_FEES.includes(Number(entryFee))) {
      setStatus("❌ Invalid entry fee. Choose 13, 23, or 50.");
      return;
    }

    setLoading(true);
    setStatus("🔍 Searching for opponent...");

    try {
      const token = localStorage.getItem("authToken");

      const response = await axios.post(
        "http://localhost:8080/api/match/start",
        { entryFee },
        {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }
      );

      const data = response.data;

      if (data.gameId) {
        setStatus("🎉 Match found! Waiting for game to start...");
        setGame({ id: data.gameId });
        setPlayerId(data.playerId);
      } else {
        setStatus("⌛ Waiting for another player to join...");
      }
    } catch (err) {
      console.error(err);
      setStatus("⚠️ " + (err.response?.data?.message || "Server error"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-lg mx-auto mt-12 p-6 bg-white border rounded-xl shadow-lg">
      <h2 className="text-2xl font-bold text-center text-indigo-700 mb-6">
        🎲 Start a Ludo Match
      </h2>

      <div className="mb-5">
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Select Entry Fee
        </label>
        <select
          value={entryFee}
          onChange={(e) => setEntryFee(Number(e.target.value))}
          className="w-full px-4 py-2 border rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
        >
          {ALLOWED_FEES.map((fee) => (
            <option key={fee} value={fee}>
              ৳ {fee}
            </option>
          ))}
        </select>
      </div>

      <button
        onClick={handleMatchRequest}
        disabled={loading}
        className={`w-full py-2 px-4 text-white font-semibold rounded-md shadow-md transition ${
          loading
            ? "bg-gray-400 cursor-not-allowed"
            : "bg-indigo-600 hover:bg-indigo-700"
        }`}
      >
        {loading ? "⏳ Finding..." : "🔍 Find Opponent"}
      </button>

      {status && (
        <div className="mt-6 text-sm text-center text-gray-700">
          <strong>Status:</strong> {status}
        </div>
      )}

      {game && game.id && (
        <div className="mt-6 p-4 text-center border border-green-400 bg-green-50 rounded-md">
          <p className="text-green-700 font-bold">✅ Game ID: {game.id}</p>
          <p className="text-green-600">👤 You are Player {playerId}</p>
        </div>
      )}
    </div>
  );
}
